    '小红书':   re.compile(r'xiaohongshu|xhslink|小红书', re.I),
}
TABLE_HINT = re.compile(r'(商品|SKU|销量|库存|单价|订单|店铺)')

def detect_encoding(path):
    """返回 (label, readable_as_utf8, used_enc)。纯 Python，不碰 file。"""
    try:
        raw = open(path, 'rb').read()
    except OSError:
        return ('unreadable', False, None)
    if not raw:
        return ('empty', True, 'utf-8')
    # 尝试 UTF-8
    try:
        raw.decode('utf-8')
        # 再细判：纯 ASCII
        try:
            raw.decode('ascii'); return ('us-ascii', True, 'utf-8')
        except UnicodeDecodeError:
            return ('utf-8', True, 'utf-8')
    except UnicodeDecodeError:
        pass
    # 非 UTF-8：尝试 GB18030（覆盖 GBK）
    try:
        raw.decode('gb18030'); return ('gb18030(GBK)', False, 'gb18030')
    except UnicodeDecodeError:
        pass
    # 兜底
    return ('binary/unknown', False, 'gb18030-replace')

def classify(text):
    for name, rx in PLAT.items():
        if rx.search(text):
            return name
    return None

def main():
